            next_dp = [0] * (n + 1)
            running_sum = 0
            for i in range(1, n + 1):
                j = i - minLength
                if j >= 0:
                    if j == 0:
                        running_sum = (running_sum + dp[0]) % MOD
                    elif s[j - 1] not in primes and s[j] in primes:
                        running_sum = (running_sum + dp[j]) % MOD
                if i == n:
                    if p == k:
                        next_dp[i] = running_sum
                elif s[i - 1] not in primes and s[i] in primes:
                    next_dp[i] = running_sum
            dp = next_dp
        return dp[n]
