class Solution {
public:
    int beautifulPartitions(std::string s, int k, int minLength) {
        auto is_prime = [](char c) {
            return c == '2' || c == '3' || c == '5' || c == '7';
        };
        int n = s.length();
        if (!is_prime(s[0]) || is_prime(s[n - 1])) return 0;
        if (k * minLength > n) return 0;
        const int MOD = 1000000007;
        std::vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int p = 1; p <= k; ++p) {
            std::vector<int> next_dp(n + 1, 0);
            int running_sum = 0;
            for (int i = 1; i <= n; ++i) {
                int j = i - minLength;
                if (j >= 0) {
                    if (j == 0) running_sum = (running_sum + dp[0]) % MOD;
                    else if (!is_prime(s[j - 1]) && is_prime(s[j])) running_sum = (running_sum + dp[j]) % MOD;
                }
                if (i == n) {
                    if (p == k) next_dp[i] = running_sum;
                } else if (!is_prime(s[i - 1]) && is_prime(s[i])) {
                    next_dp[i] = running_sum;
                }
            }
            dp = std::move(next_dp);
        }
        return dp[n];
    }
};

class Solution {
    public int beautifulPartitions(String s, int k, int minLength) {
        int n = s.length();
        if (!isPrime(s.charAt(0)) || isPrime(s.charAt(n - 1))) return 0;
        if (k * minLength > n) return 0;
        int MOD = 1_000_000_007;
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int p = 1; p <= k; p++) {
            int[] nextDp = new int[n + 1];
            int runningSum = 0;
            for (int i = 1; i <= n; i++) {
                int j = i - minLength;
                if (j >= 0) {
                    if (j == 0) runningSum = (runningSum + dp[0]) % MOD;
                    else if (!isPrime(s.charAt(j - 1)) && isPrime(s.charAt(j))) runningSum = (runningSum + dp[j]) % MOD;
                }
                if (i == n) {
                    if (p == k) nextDp[i] = runningSum;
                } else if (!isPrime(s.charAt(i - 1)) && isPrime(s.charAt(i))) {
                    nextDp[i] = runningSum;
                }
            }
            dp = nextDp;
        }
        return dp[n];
    }
    private boolean isPrime(char c) {
        return c == '2' || c == '3' || c == '5' || c == '7';
    }
}

